{% set BEAD = {'awaits-human':'#f9e2af','working':'#fab387','blocked':'#74c7ec','idle':'#585b70','done':'#45475a'} %}{% macro fname(f, badge, ago, wide) %}{% set cap = 10 - (1 if wide else 0) - (0 if not badge else 2 + (badge | string | length)) - (3 if ago else 0) %}{% set cut = cap - 1 %}{% if (f | length) > cap + 1 %}{{ f[:cut] }}…{% else %}{{ f }}{% endif %}{% endmacro %}{% macro beads(fl, max) %}{% for d in fl.demands %}{% if loop.index0 < max %}{% if loop.index0 > 0 and d != fl.demands[loop.index0 - 1] %} {% endif %}<span foreground='{{ BEAD[d] | default('#585b70') }}'>▮</span>{% endif %}{% endfor %}<span size='small' foreground='#7f849c'> {{ fl.live }}/{{ fl.total }}</span>{% endmacro %}{% macro fleetlabel(fl, folder, ago, wide) %}<span weight='bold' foreground='#89b4fa'>{{ fname(folder, fl.awaiting, ago, wide) }}</span>{% if fl.awaiting %} <span weight='bold' foreground='#f9e2af'>⚠{{ fl.awaiting }}</span>{% endif %}{% endmacro %}{% if active %}<active/>{% endif %}{% set rows = items | default(sessions | default([{"kind":"app","app":app,"app_icon":app_icon,"title":title}])) %}{% set prompting = (rows | selectattr('state', 'eq', 'prompt') | list | length) > 0 %}{% if prompting %}<pulse>{% endif %}{% if (rows | length) == 1 %}{% set row = rows[0] %}{% if row.kind == 'session' or (row.kind != 'app' and row.state is defined) %}<span size='xx-large' weight='bold' foreground='#cdd6f4'>{{ shortcut }}</span> <status state='{{ row.state }}' level='{{ row.idle_level | default(0) }}' ago='{{ row.idle_ago | default('') }}'/> {% if row.fleet %}{{ fleetlabel(row.fleet, row.folder, row.idle_ago if row.state == 'idle' else '', row.state in ['working', 'shell']) }}
{{ beads(row.fleet, 13) }}
<wrap><span size='small' foreground='#cdd6f4'>{% set ask = row.fleet.needs or row.fleet.detail or '' %}{% set who = row.fleet.neediest | default('') %}{% set head = (who[:12] ~ '…') if (who | length) > 13 else who %}{% set line = (head ~ ': ' ~ ask) if (who and ask) else (ask or head) %}{{ line[:34] }}{% if line | length > 34 %}…{% endif %}</span></wrap>{% else %}<span weight='bold' foreground='#89b4fa'>{{ fname(row.folder, row.unpushed if row.state != 'idle' else 0, row.idle_ago if row.state == 'idle' else '', row.state in ['working', 'shell']) }}</span>{% if row.unpushed and row.state != 'idle' %} <span weight='bold' foreground='#a6e3a1'>↑{{ row.unpushed }}</span>{% endif %}
<wrap><span foreground='#cdd6f4'>{% set t = row.title | default('') %}{{ t[:44] }}{% if (t | length) > 44 %}…{% endif %}</span></wrap>{% endif %}{% else %}{% set ico = row.app_icon | default('app') %}{% if '/' in ico %}<icon watermark='1' src='{{ ico }}'/>{% else %}<icon watermark='1' name='{{ ico }}'/>{% endif %}<span size='xx-large' weight='bold' foreground='#cdd6f4'>{{ shortcut }}</span><sep/><span weight='bold' foreground='#89b4fa'>{{ row.app }}</span>
<wrap><span foreground='#cdd6f4'>{% set t = row.title | default('') %}{{ t[:44] }}{% if (t | length) > 44 %}…{% endif %}</span></wrap>{% endif %}{% else %}<gutter><span size='240%' weight='bold' foreground='#cdd6f4'>{{ shortcut }}</span></gutter>{% for row in rows %}{% if row.kind == 'session' or (row.kind != 'app' and row.state is defined) %}<status state='{{ row.state }}' level='{{ row.idle_level | default(0) }}' ago='{{ row.idle_ago | default('') }}'/> {% if row.fleet %}{{ fleetlabel(row.fleet, row.folder, row.idle_ago if row.state == 'idle' else '', row.state in ['working', 'shell']) }}{% else %}<span weight='bold' foreground='#89b4fa'>{{ fname(row.folder, row.unpushed if row.state != 'idle' else 0, row.idle_ago if row.state == 'idle' else '', row.state in ['working', 'shell']) }}</span>{% if row.unpushed and row.state != 'idle' %} <span weight='bold' foreground='#a6e3a1'>↑{{ row.unpushed }}</span>{% endif %}{% endif %}{% else %}{% set ico = row.app_icon | default('app') %}{% if '/' in ico %}<icon src='{{ ico }}' size='1.1'/>{% else %}<icon name='{{ ico }}' size='1.1'/>{% endif %} <span weight='bold' foreground='#89b4fa'>{{ row.app }}</span>{% endif %}
{% if row.fleet %}{{ beads(row.fleet, 9) }}{% else %}<tickerbox width='116'><span size='small' foreground='#cdd6f4'>{{ row.title | default('') }}</span></tickerbox>{% endif %}{% if not loop.last %}
{% endif %}{% endfor %}{% endif %}{% if prompting %}</pulse>{% endif %}
